<?php
declare(strict_types=1);session_start();require_once __DIR__.'/config/sales_step15.php';if(empty($_SESSION['return15_csrf']))$_SESSION['return15_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['return15_csrf'];$error=null;$success=null;$allocations=[];$returns=[];$orderFilter=(int)($_GET['order']??0);
try{$pdo=business_db();sales_step15_ensure($pdo);sales_step15_backfill($pdo);$ctx=sales_step15_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$id=sales_step15_post_return($pdo,(int)$_POST['allocation_id'],(float)$_POST['quantity'],(string)$_POST['return_date'],(float)$_POST['credit_amount'],trim((string)$_POST['reason']));$success='Customer Return #'.$id.' posted and stock restored to the original batch.';}$allocations=sales_step15_returnable_allocations($pdo,$orgId);if($orderFilter>0)$allocations=array_values(array_filter($allocations,static fn($a)=>(int)$a['order_id']===$orderFilter));$stmt=$pdo->prepare("SELECT r.*,COALESCE(c.customer_name,cl.customer_name_snapshot,q.customer_name,'Unlinked customer') customer_name,COUNT(ri.id) item_count,COALESCE(SUM(ri.quantity_returned),0) total_qty FROM sales_returns r LEFT JOIN sales_customer_links cl ON cl.organization_id=r.organization_id AND cl.order_id=r.order_id LEFT JOIN crm_customers c ON c.id=cl.customer_id AND c.organization_id=r.organization_id LEFT JOIN product_quote_order_links ql ON ql.organization_id=r.organization_id AND ql.order_id=r.order_id LEFT JOIN product_quotes q ON q.id=ql.quote_id AND q.organization_id=r.organization_id LEFT JOIN sales_return_items ri ON ri.organization_id=r.organization_id AND ri.sales_return_id=r.id WHERE r.organization_id=? GROUP BY r.id ORDER BY r.return_date DESC,r.id DESC");$stmt->execute([$orgId]);$returns=$stmt->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
function sr_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function sr_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}function sr_n(mixed $v):string{$x=number_format((float)$v,3,'.','');return rtrim(rtrim($x,'0'),'.');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Customer Returns - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="sales_fulfillment.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 15 • Customer Returns</small></span></a><div class="os-top-actions"><a class="os-btn" href="sales_delivery.php">Delivery</a><a class="os-btn" href="sales_refunds.php">Refunds</a><a class="os-btn primary" href="sales_fulfillment.php">Fulfillment</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">After-Sales</div><nav class="os-nav"><a href="customer_center.php"><i class="dot"></i>Customers</a><a href="sales_fulfillment.php"><i class="dot"></i>Fulfillment</a><a href="sales_invoice.php"><i class="dot"></i>Invoices</a><a href="sales_delivery.php"><i class="dot"></i>Delivery</a><a class="active" href="sales_returns.php"><i class="dot"></i>Returns</a><a href="sales_refunds.php"><i class="dot"></i>Refunds</a><a href="sales_receivables.php"><i class="dot"></i>Receivables</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 15E • CUSTOMER RETURN / CREDIT NOTE</div><h1>Return only what was actually sold and allocated from inventory.</h1><p>Each return is tied to the original sale allocation and batch. The actual approved Customer Credit Note amount is entered explicitly.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'RETURN CENTER LIVE':'Review required' ?></span><span class="os-chip"><?= count($allocations) ?> returnable allocations</span><span class="os-chip"><?= count($returns) ?> return records</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Return diagnostic:</strong> <?= sr_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Posted:</strong> <?= sr_h($success) ?></div><?php endif;?><?php if(!$error):?><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-5"><h2>Post Customer Return</h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= sr_h($csrf) ?>"><label>Sold Batch Allocation<select name="allocation_id" required><option value="">Choose returnable sale line…</option><?php foreach($allocations as $a):?><option value="<?= (int)$a['allocation_id'] ?>">Order #<?= (int)$a['order_id'] ?> • <?= sr_h($a['linked_customer']?:$a['customer_name_snapshot']?:$a['customer_name']?:'Customer') ?> • <?= sr_h($a['stock_no'].' • '.$a['product_name_snapshot'].' • Batch '.$a['batch_code'].' • Returnable '.sr_n($a['returnable_quantity'])) ?></option><?php endforeach;?></select></label><label>Return Quantity<input type="number" min="0.001" step="0.001" name="quantity" required></label><label>Return Date<input type="date" name="return_date" value="<?= sr_h(date('Y-m-d')) ?>" required></label><label>Actual Customer Credit Note Amount<input type="number" min="0" step="0.01" name="credit_amount" required><small>Enter the approved value; it is not inferred from MRP or sale price.</small></label><label>Reason<textarea name="reason" minlength="5" rows="3" required></textarea></label><button>Post Return & Restore Stock →</button></form></article><article class="os-card pp-span-7"><h2>Returnable Sold Stock</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Order</th><th>Customer</th><th>Product</th><th>Batch</th><th>Sold</th><th>Returned</th><th>Returnable</th><th>Batch Stock</th></tr></thead><tbody><?php foreach($allocations as $a):?><tr><td>#<?= (int)$a['order_id'] ?><small><?= sr_h($a['order_date']) ?></small></td><td><?= sr_h($a['linked_customer']?:$a['customer_name_snapshot']?:$a['customer_name']?:'—') ?></td><td><b><?= sr_h($a['stock_no']) ?></b><small><?= sr_h($a['product_name_snapshot']) ?></small></td><td><?= sr_h($a['batch_code']) ?></td><td><?= sr_h(sr_n($a['allocated_quantity'])) ?></td><td><?= sr_h(sr_n($a['returned_quantity'])) ?></td><td><b><?= sr_h(sr_n($a['returnable_quantity'])) ?></b></td><td><?= sr_h(sr_n($a['batch_stock'])) ?></td></tr><?php endforeach;?><?php if(!$allocations):?><tr><td colspan="8">No returnable sold allocations yet.</td></tr><?php endif;?></tbody></table></div><h2 style="margin-top:18px">Customer Return / Credit Note History</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Date</th><th>Return</th><th>Order</th><th>Customer</th><th>Qty</th><th>Credit</th><th>Reason</th></tr></thead><tbody><?php foreach($returns as $r):?><tr><td><?= sr_h($r['return_date']) ?></td><td><b><?= sr_h($r['return_number']) ?></b></td><td>#<?= (int)$r['order_id'] ?></td><td><?= sr_h($r['customer_name']) ?></td><td><?= sr_h(sr_n($r['total_qty'])) ?></td><td><b><?= sr_m($r['total_credit']) ?></b></td><td><?= sr_h($r['reason']) ?></td></tr><?php endforeach;?><?php if(!$returns):?><tr><td colspan="7">No customer returns yet.</td></tr><?php endif;?></tbody></table></div></article></section><?php endif;?><div class="os-footer-note"><strong>Return rule:</strong> stock returns to the original allocated batch; invoice remains unchanged and return credit is a separate after-sales fact.</div></main></div></body></html>